package com.example.touristpermit.document;

import org.springframework.core.io.Resource;

import java.io.InputStream;
import java.time.LocalDate;
import java.util.UUID;

/**
 * Storage for uploaded files (documents, destination photos). Implementations:
 * {@link LocalFileStorage} (single instance) and {@link S3FileStorage} (shared object
 * storage for several backend instances), selected with {@code STORAGE_TYPE}.
 * Keys are generated by the system and never derived from user input.
 */
public interface FileStorageService {

    /** Stores the stream and returns its storage key (relative path). */
    String store(InputStream content, String extension);

    Resource load(String key);

    void deleteQuietly(String key);

    /** {@code yyyy/MM/<uuid>.<ext>} — random, unguessable and date-partitioned. */
    static String newKey(LocalDate date, String extension) {
        return "%d/%02d/%s.%s".formatted(date.getYear(), date.getMonthValue(), UUID.randomUUID(), extension);
    }
}
